function validate([text]) {
  if (typeof text !== 'string' || text.length < 1 || text.length > 20000) return 'text needs 1 to 2 * 10^4 letters.';
  if (!/^[a-z]+$/.test(text)) return 'text uses lowercase English letters only.';
  return null;
}

