function maxRepOpt1(text) {
  const total = new Map();
  for (const letter of text) {
    total.set(letter, (total.get(letter) ?? 0) + 1);
  }
  // Split text into runs: [letter, length] for each block of one repeated letter.
  const runs = [];
  let start = 0;
  for (let i = 1; i <= text.length; i++) {
    if (i === text.length || text[i] !== text[start]) {
      runs.push([text[start], i - start]);
      start = i;
    }
  }
  let best = 0;
  for (let i = 0; i < runs.length; i++) {
    const [letter, length] = runs[i];
    // Extend the run by one copy of its letter taken from somewhere else, if one exists.
    best = Math.max(best, Math.min(length + 1, total.get(letter)));
    // Two runs of the same letter with one other letter between them can be merged.
    if (i + 2 < runs.length && runs[i + 1][1] === 1 && runs[i + 2][0] === letter) {
      const merged = length + runs[i + 2][1];
      best = Math.max(best, Math.min(merged + 1, total.get(letter)));
    }
  }
  return best;
}

