function maxRepOpt1(text) {
  const longest = chars => {
    let top = 0, streak = 0;
    for (let k = 0; k < chars.length; k++) {
      streak = k > 0 && chars[k] === chars[k - 1] ? streak + 1 : 1;
      top = Math.max(top, streak);
    }
    return top;
  };
  const chars = text.split('');
  let best = longest(chars);
  // Try every possible swap and measure the result.
  for (let a = 0; a < chars.length; a++) {
    for (let b = a + 1; b < chars.length; b++) {
      [chars[a], chars[b]] = [chars[b], chars[a]];
      best = Math.max(best, longest(chars));
      [chars[a], chars[b]] = [chars[b], chars[a]];
    }
  }
  return best;
}

