function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  if (size === 'small') {
    const alphabet = 'abc'.slice(0, 1 + pick(3));
    const n = 1 + pick(12);
    let text = '';
    while (text.length < n) {
      // Runs of one letter, often broken by a single different letter.
      const letter = alphabet[pick(alphabet.length)];
      text += letter.repeat(1 + pick(rand() < 0.5 ? 1 : 4));
    }
    return [text.slice(0, n)];
  }
  const alphabet = 'abcdefghijklmnopqrstuvwxyz'.slice(0, 2 + pick(5));
  const n = 10000;
  let text = '';
  while (text.length < n) {
    const letter = alphabet[pick(alphabet.length)];
    text += letter.repeat(1 + pick(rand() < 0.5 ? 2 : 40));
  }
  return [text.slice(0, n)];
}
